package com.johnny.hotel.financeexpense;import jakarta.validation.constraints.*;import java.math.*;public final class ExpenseReversalCommands{private ExpenseReversalCommands(){}public record Request(@NotNull@DecimalMin("0.01")@Digits(integer=10,fraction=2)BigDecimal amount,@NotBlank@Size(max=500)String reason,@NotBlank@Size(min=8,max=100)String requestKey){}public record Approve(@NotBlank@Size(min=8,max=100)String requestKey,@AssertTrue(message="Actual returned funds must be confirmed")boolean fundsReturnedConfirmed,@Size(max=100)String externalReference){}public record Reject(@NotBlank@Size(min=8,max=100)String requestKey,@NotBlank@Size(max=500)String reason){} }
